package world

import "testing"

func TestZZRandomCrossCheck(t *testing.T) {
	seeds := []int64{-13, -1, 0, 1, 8, 42, 1009}
	rstate := uint64(0xC0FFEE)
	rnd := func() uint64 {
		rstate += 0x9E3779B97F4A7C15
		z := rstate
		z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9
		z = (z ^ (z >> 27)) * 0x94D049BB133111EB
		return z ^ (z >> 31)
	}
	total, feasible := 0, 0
	for _, n := range []int{6, 7} {
		locs := make([]string, n)
		for i := range locs {
			locs[i] = string(rune('a' + i))
		}
		var all []Edge
		for i := 0; i < n; i++ {
			for j := i + 1; j < n; j++ {
				all = append(all, Edge{locs[i], locs[j]})
			}
		}
		for trial := 0; trial < 300; trial++ {
			var req, ban []Edge
			for _, e := range all {
				switch rnd() % 4 {
				case 0:
					req = append(req, e)
				case 1:
					ban = append(ban, e)
				}
			}
			max := len(all)
			for rc := n - 2; rc <= max; rc++ {
				ok := independentFeasible(t, locs, req, ban, rc)
				for _, seed := range seeds {
					total++
					if ok {
						feasible++
						w, err := GenerateWorld(GenerateRequest{
							Seed: seed, Locations: locs, Required: req, Banned: ban,
							RoadCount: rc, RulesVersion: "v1",
						})
						if err != nil {
							t.Fatalf("n=%d rc=%d seed=%d 有解却失败: %v\nreq=%v ban=%v", n, rc, seed, err, req, ban)
						}
						assertMapShape(t, w.Snapshot(), GenerateRequest{
							Locations: locs, Required: req, Banned: ban, RoadCount: rc,
						})
					} else {
						w, err := GenerateWorld(GenerateRequest{
							Seed: seed, Locations: locs, Required: req, Banned: ban,
							RoadCount: rc, RulesVersion: "v1",
						})
						if err == nil {
							t.Fatalf("n=%d rc=%d 无解却成功: %v\nreq=%v ban=%v", n, rc, w.Snapshot().Rules.Edges, req, ban)
						}
						if _, ok := err.(*RuleError); !ok {
							t.Fatalf("n=%d rc=%d 期望 *RuleError, got %T", n, rc, err)
						}
					}
				}
			}
		}
	}
	t.Logf("交叉验证 %d 个请求（其中 %d 个有解）", total, feasible)
}
EOF
